input.content:
// make-photos.mjs — turns tee.png into 4 product photos with Modelfy and prints the links.
//
// Usage:  node --env-file=.env make-photos.mjs
// Needs:  MODELFY_API_KEY in the environment (a sandbox key "mfy_test_…" is free and spends nothing).

import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const MCP_URL = "https://mcp-dev.modelfy.ai/mcp";
const IMAGE_PATH = path.join(path.dirname(fileURLToPath(import.meta.url)), "tee.png");
const PHOTOS = 4;

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env or export it, then run again.");
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP (JSON-RPC over POST) ----------

let nextId = 1;

async function rpc(method, params) {
  const id = nextId++;
  const res = await fetch(MCP_URL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
    },
    body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`Modelfy ${method} failed: HTTP ${res.status} ${text.slice(0, 300)}`);

  // The server answers either plain JSON or a single SSE event ("data: {...}").
  let message;
  if ((res.headers.get("content-type") || "").includes("text/event-stream")) {
    const line = text.split("\n").find((l) => l.startsWith("data:"));
    message = JSON.parse(line.slice(5));
  } else {
    message = JSON.parse(text);
  }
  if (message.error) throw new Error(`Modelfy ${method}: ${message.error.message}`);
  return message.result;
}

// Calls a tool and returns its structured result. Throws on tool errors with the Modelfy error code.
async function callTool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  const data = result.structuredContent ?? parseTextJson(result);
  if (result.isError) {
    const err = data?.error ?? {};
    const msg = err.message ?? result.content?.[0]?.text ?? "unknown error";
    const next = err.next_step ? ` Next step: ${err.next_step}` : "";
    throw new Error(`${name} failed [${err.code ?? "ERROR"}]: ${msg}.${next}`);
  }
  return data;
}

function parseTextJson(result) {
  for (const block of result.content ?? []) {
    try {
      return JSON.parse(block.text);
    } catch {
      // not JSON; keep looking
    }
  }
  return {};
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- Steps -------------------------------------------------------------------

async function uploadProductPhoto() {
  const bytes = await readFile(IMAGE_PATH);
  const contentType = "image/png";

  // 1. Announce the file; Modelfy returns a presigned PUT URL for it.
  const session = await callTool("create_upload_session", {
    files: [{ content_type: contentType, bytes: bytes.length }],
  });
  const upload = session.uploads[0];

  // 2. Send the bytes straight to that URL, with exactly the headers it returned.
  const put = await fetch(upload.put_url, {
    method: "PUT",
    headers: upload.headers,
    body: bytes,
  });
  if (!put.ok) throw new Error(`Uploading tee.png failed: HTTP ${put.status}`);

  // 3. Wait until Modelfy has accepted the file.
  for (let attempt = 0; attempt < 30; attempt++) {
    const status = await callTool("get_uploaded_photos", { session_id: session.session_id });
    if (status.rejected?.length) {
      throw new Error(`Modelfy rejected tee.png: ${status.rejected[0].reason ?? JSON.stringify(status.rejected[0])}`);
    }
    if (status.ready_upload_ids?.length) return status.ready_upload_ids[0];
    await sleep(1000);
  }
  throw new Error("Timed out waiting for Modelfy to accept tee.png");
}

async function main() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });

  console.log("Uploading tee.png…");
  const uploadId = await uploadProductPhoto();

  // Studio shot on white, product only (no model), 4:5, four photos.
  console.log("Planning 4 photos…");
  const plan = await callTool("plan_photos", {
    products: [{ upload_ids: [uploadId], name: "Linen T-shirt" }],
    mode: "studio",
    background_color: "white",
    aspect_ratio: "4:5",
    photos_per_product: PHOTOS,
    direction: "clean product shot, soft even light, linen texture visible",
    locale: "en",
  });
  if (plan.enough_credits === false) {
    throw new Error(`Not enough credits: this costs ${plan.credits}, balance is ${plan.balance}.`);
  }
  console.log(`Price: ${plan.credits} credits for ${plan.photos} photos (balance ${plan.balance}).`);

  // A live key's budget is the consent; a chat (OAuth) connection would need user_confirmed.
  console.log("Launching…");
  const launch = await callTool("generate_photos", { quote_id: plan.quote_id });
  const sessionId = launch.session_id;
  console.log(`Session ${sessionId} started.`);

  // Wait for the photos to finish.
  let session;
  do {
    session = await callTool("get_photo_session", { session_id: sessionId, wait_seconds: 45 });
    console.log(`Status: ${session.status}`);
  } while (session.status === "running");

  const photos = (session.photos ?? []).filter((p) => p.url ?? p.link ?? p.image_url);
  console.log("");
  if (!photos.length) {
    throw new Error(`No photos were made (status: ${session.status}).`);
  }
  for (const p of photos) {
    console.log(p.url ?? p.link ?? p.image_url);
  }
  if (session.web_url) {
    console.log("");
    console.log(`All photos: ${session.web_url}`);
  }
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

