// make-photos.mjs — turn tee.png into 4 product photos with Modelfy.
//
// Usage:  node --env-file=.env make-photos.mjs
// Needs:  MODELFY_API_KEY in the environment (Bearer token, mfy_test_… or mfy_live_…).
// Optional env: PHOTO_FILE (default tee.png), ASPECT_RATIO (default 4:5),
//               PHOTO_COUNT (default 4), BACKGROUND_COLOR (default "white").

import { readFile } from "node:fs/promises";
import { basename, extname } from "node:path";
import { fileURLToPath } from "node:url";

const MCP_URL = "https://mcp-dev.modelfy.ai/mcp";
const API_KEY = process.env.MODELFY_API_KEY;
const FILE = process.env.PHOTO_FILE ?? fileURLToPath(new URL("./tee.png", import.meta.url));
const ASPECT_RATIO = process.env.ASPECT_RATIO ?? "4:5";
const PHOTO_COUNT = Number(process.env.PHOTO_COUNT ?? 4);
const BACKGROUND_COLOR = process.env.BACKGROUND_COLOR ?? "white";
const PRODUCT_NAME = "Linen T-shirt";

const CONTENT_TYPES = { ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp", ".heic": "image/heic" };

if (!API_KEY) {
  console.error("MODELFY_API_KEY is not set. Put it in .env and run: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

// ---------- MCP client (Streamable HTTP, JSON-RPC) ----------
let sessionId;
let rpcId = 0;

async function rpc(method, params, { notify = false } = {}) {
  const body = notify ? { jsonrpc: "2.0", method, params } : { jsonrpc: "2.0", id: ++rpcId, method, params };
  const res = await fetch(MCP_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      accept: "application/json, text/event-stream",
      authorization: `Bearer ${API_KEY}`,
      ...(sessionId ? { "mcp-session-id": sessionId } : {}),
    },
    body: JSON.stringify(body),
  });
  sessionId ??= res.headers.get("mcp-session-id") ?? undefined;
  if (!res.ok) throw new Error(`HTTP ${res.status} from Modelfy: ${(await res.text()).slice(0, 300)}`);
  if (notify) return null;
  const text = await res.text();
  const line = text.match(/^data: (.*)$/m);
  return JSON.parse(line ? line[1] : text);
}

async function init() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  await rpc("notifications/initialized", {}, { notify: true });
}

// Calls a tool and returns its structured result. Throws on tool errors with Modelfy's code and next_step.
async function call(name, args = {}) {
  const reply = await rpc("tools/call", { name, arguments: args });
  if (reply.error) throw new Error(`${name}: ${reply.error.message}`);
  const result = reply.result;
  const data = result.structuredContent ?? JSON.parse(result.content.find((c) => c.type === "text" && c.text.startsWith("{"))?.text ?? "{}");
  if (result.isError) {
    const err = data.error ?? {};
    const msg = result.content?.find((c) => c.type === "text")?.text ?? "unknown error";
    throw new Error(`${name} failed [${err.code ?? "ERROR"}]: ${msg}${err.next_step ? ` Next step: ${err.next_step}` : ""}`);
  }
  return data;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---------- 1. Upload the product photo from this machine ----------
async function uploadPhoto() {
  const bytes = await readFile(FILE);
  const contentType = CONTENT_TYPES[extname(FILE).toLowerCase()];
  if (!contentType) throw new Error(`Unsupported file type for ${FILE} (use PNG, JPEG, WebP or HEIC)`);

  const session = await call("create_upload_session", { files: [{ content_type: contentType, bytes: bytes.length }] });
  const target = session.uploads[0];

  // The bytes go straight from this script to Modelfy, never through the model.
  const put = await fetch(target.put_url, { method: "PUT", headers: target.headers, body: bytes });
  if (!put.ok) throw new Error(`Upload of ${basename(FILE)} failed: HTTP ${put.status}`);

  for (let i = 0; i < 20; i++) {
    const status = await call("get_uploaded_photos", { session_id: session.session_id });
    const ready = status.ready?.find((p) => p.upload_id === target.upload_id) ?? status.ready?.[0];
    if (ready) return ready.upload_id ?? target.upload_id;
    if (status.rejected?.length) throw new Error(`Modelfy rejected ${basename(FILE)}: ${status.rejected[0].reason}`);
    await sleep(1500);
  }
  throw new Error(`Timed out waiting for Modelfy to accept ${basename(FILE)}`);
}

// ---------- main ----------
await init();

const account = await call("get_account");
console.log(`Account: ${account.plan}, ${account.credits} credits${account.sandbox ? " (sandbox: photos are samples, nothing is spent)" : ""}`);

const uploadId = await uploadPhoto();
console.log(`Uploaded ${basename(FILE)} -> ${uploadId}`);

const plan = await call("plan_photos", {
  products: [{ upload_ids: [uploadId], name: PRODUCT_NAME }],
  mode: "studio",
  background_color: BACKGROUND_COLOR,
  aspect_ratio: ASPECT_RATIO,
  photos_per_product: PHOTO_COUNT,
  locale: "en",
});
console.log(`Plan: ${plan.photos ?? PHOTO_COUNT} photos for ${plan.credits} credits (balance ${plan.balance}, enough: ${plan.enough_credits})`);
if (plan.enough_credits === false) throw new Error("Not enough credits for this session.");

const launch = await call("generate_photos", { quote_id: plan.quote_id, user_confirmed: true });
const sessionIdM = launch.session_id;
console.log(`Launched session ${sessionIdM}`);

// ---------- 2. Wait for the photos ----------
let session;
do {
  session = await call("get_photo_session", { session_id: sessionIdM, wait_seconds: 45 });
  console.log(`Status: ${session.status}`);
} while (session.status === "running");

const photos = session.photos ?? [];
console.log(`\nSession ${session.status}. ${photos.filter((p) => p.url || p.link).length} of ${PHOTO_COUNT} photos:`);
for (const p of photos) {
  const link = p.url ?? p.link ?? p.web_url;
  console.log(`${link ?? "(no link)"}${p.error ? `  [failed: ${p.error}]` : ""}`);
}
if (session.web_url) console.log(`\nAll photos: ${session.web_url}`);

if (session.status === "failed" || session.status === "cancelled") process.exit(1);

