import fs from "node:fs";
const env = Object.fromEntries(fs.readFileSync("/work/.env","utf8").split("\n").filter(Boolean).map(l=>{const i=l.indexOf("=");return [l.slice(0,i),l.slice(i+1)]}));
const KEY = env.MODELFY_API_KEY;
let id=10;
async function call(name, args={}) {
  const r = await fetch("https://mcp-dev.modelfy.ai/mcp",{method:"POST",headers:{Authorization:`Bearer ${KEY}`,"Content-Type":"application/json",Accept:"application/json, text/event-stream","MCP-Protocol-Version":"2025-06-18"},body:JSON.stringify({jsonrpc:"2.0",id:id++,method:"tools/call",params:{name,arguments:args}})});
  const txt = await r.text();
  const data = txt.split("\n").filter(l=>l.startsWith("data: ")).map(l=>l.slice(6)).join("");
  return JSON.parse(data);
}
for (const [n,a] of JSON.parse(process.argv[2])) { const out = await call(n,a); console.log("##",n); console.log(JSON.stringify(out).slice(0,2500)); }
