// make-photos.mjs
// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy and prints the links.
//
// Run:  node --env-file=.env make-photos.mjs
// Needs MODELFY_API_KEY in the environment (a sandbox key is free; nothing is spent).

import { readFile, stat } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const MCP_URL = "https://mcp-dev.modelfy.ai/mcp";
const PROTOCOL_VERSION = "2025-06-18";
const PRODUCT_IMAGE = path.join(path.dirname(fileURLToPath(import.meta.url)), "tee.png");
const PRODUCT_NAME = "Linen T-shirt";
const PHOTO_COUNT = 4;
const ASPECT_RATIO = "4:5";

const KEY = process.env.MODELFY_API_KEY;
if (!KEY) {
  console.error("MODELFY_API_KEY is not set. Put it in .env (see the header of this file).");
  process.exit(1);
}

// ---- MCP client (Streamable HTTP, JSON-RPC over POST) ----------------------

let nextId = 1;
let sessionId = null;

async function rpc(method, params) {
  const headers = {
    Authorization: `Bearer ${KEY}`,
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "MCP-Protocol-Version": PROTOCOL_VERSION,
  };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;

  const res = await fetch(MCP_URL, {
    method: "POST",
    headers,
    body: JSON.stringify({ jsonrpc: "2.0", id: nextId++, method, params }),
  });
  sessionId = res.headers.get("mcp-session-id") ?? sessionId;
  const text = await res.text();
  if (!res.ok) throw new Error(`HTTP ${res.status} from Modelfy: ${text.slice(0, 300)}`);

  // The server answers as an SSE stream ("data: {...}") or plain JSON.
  const payload = text.includes("data:")
    ? text.split("\n").filter((l) => l.startsWith("data:")).map((l) => l.slice(5).trim()).join("")
    : text;
  const msg = JSON.parse(payload);
  if (msg.error) throw new Error(`MCP error: ${msg.error.message}`);
  return msg.result;
}

async function init() {
  await rpc("initialize", {
    protocolVersion: PROTOCOL_VERSION,
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
}

// Calls a tool and returns its structuredContent. Throws with the Modelfy error code on failure.
async function tool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  const data = result.structuredContent ?? {};
  if (result.isError) {
    const err = data.error ?? {};
    const text = result.content?.map((c) => c.text).join(" ") ?? "";
    const e = new Error(`${name} failed [${err.code ?? "ERROR"}]: ${err.message ?? text}${err.next_step ? ` Next: ${err.next_step}` : ""}`);
    e.code = err.code;
    throw e;
  }
  return data;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- Steps -----------------------------------------------------------------

async function uploadProductImage() {
  const bytes = (await stat(PRODUCT_IMAGE)).size;
  const contentType = "image/png";
  const session = await tool("create_upload_session", { files: [{ content_type: contentType, bytes }] });
  const upload = session.uploads[0];

  const body = await readFile(PRODUCT_IMAGE);
  const put = await fetch(upload.put_url, {
    method: "PUT",
    headers: upload.headers,
    body,
  });
  if (!put.ok) throw new Error(`Upload of ${PRODUCT_IMAGE} failed: HTTP ${put.status}`);

  // The file becomes usable after Modelfy checks it; poll until it is ready or rejected.
  for (let i = 0; i < 30; i++) {
    const status = await tool("get_uploaded_photos", { session_id: session.session_id });
    if (status.rejected?.length) {
      throw new Error(`Product photo rejected: ${JSON.stringify(status.rejected)}`);
    }
    if (status.ready_upload_ids?.length) return status.ready_upload_ids[0];
    await sleep(2000);
  }
  throw new Error("Product photo was still pending after 60 seconds.");
}

// Takes the first ready model and the first ready place from the catalog (never invented ids).
async function pickModelAndPlace() {
  const { models } = await tool("list_models");
  const { backgrounds } = await tool("list_backgrounds");
  const model = models.find((m) => m.ready);
  const place = backgrounds.find((b) => b.ready);
  if (!place) throw new Error("No ready background in the Modelfy catalog.");
  return { modelIds: model ? [model.id] : [], background: place };
}

async function waitForSession(sessionId) {
  for (;;) {
    const s = await tool("get_photo_session", { session_id: sessionId, wait_seconds: 45 });
    if (s.status !== "running") return s;
    console.error(`  still running (${s.status})...`);
  }
}

// ---- Main ------------------------------------------------------------------

async function main() {
  await init();

  console.error("Uploading product photo...");
  const uploadId = await uploadProductImage();

  console.error("Choosing a model and a place...");
  const { modelIds, background } = await pickModelAndPlace();

  console.error("Planning the session...");
  const plan = await tool("plan_photos", {
    products: [{ upload_ids: [uploadId], name: PRODUCT_NAME }],
    mode: "place",
    background_id: background.id,
    model_ids: modelIds,
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTO_COUNT,
    locale: "en",
  });
  console.error(`Price: ${plan.credits} credits for ${PHOTO_COUNT} photos (balance ${plan.balance}).`);
  if (plan.enough_credits === false) throw new Error("Not enough credits for this session.");

  console.error("Launching...");
  const launch = await tool("generate_photos", { quote_id: plan.quote_id });
  const sessionRef = launch.session_id;

  console.error("Waiting for the photos...");
  const done = await waitForSession(sessionRef);
  if (done.status === "failed" || done.status === "cancelled") {
    throw new Error(`Session ${done.status}; credits were refunded.`);
  }

  const links = (done.photos ?? []).map((p) => p.url ?? p.link ?? p.web_url).filter(Boolean);
  if (done.web_url) console.error(`All photos: ${done.web_url}`);
  for (const link of links) console.log(link);
  if (!links.length) {
    console.error("No photo links in the response:");
    console.error(JSON.stringify(done, null, 2));
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

