// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy and prints the links.
// Usage: node --env-file=.env make-photos.mjs
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const MCP_URL = "https://mcp-dev.modelfy.ai/mcp";
const PRODUCT_IMAGE = join(dirname(fileURLToPath(import.meta.url)), "tee.png");
const PRODUCT_NAME = "Linen T-shirt";
const PHOTOS = 4;
const ASPECT_RATIO = "4:5";

const KEY = process.env.MODELFY_API_KEY;
if (!KEY) {
  console.error("MODELFY_API_KEY is not set. Run with: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

// ---- minimal MCP client over Streamable HTTP ----
let sessionId;
let nextId = 1;

async function rpc(method, params) {
  const res = await fetch(MCP_URL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${KEY}`,
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      "MCP-Protocol-Version": "2025-06-18",
      ...(sessionId ? { "Mcp-Session-Id": sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", id: nextId++, method, params }),
  });
  sessionId ??= res.headers.get("mcp-session-id") ?? undefined;
  const text = await res.text();
  if (!res.ok) throw new Error(`HTTP ${res.status} from Modelfy: ${text.slice(0, 300)}`);
  const line = text.split("\n").find((l) => l.startsWith("data:"));
  const msg = JSON.parse(line ? line.slice(5) : text);
  if (msg.error) throw new Error(`MCP error: ${JSON.stringify(msg.error)}`);
  return msg.result;
}

async function notify(method) {
  await fetch(MCP_URL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${KEY}`,
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      "MCP-Protocol-Version": "2025-06-18",
      ...(sessionId ? { "Mcp-Session-Id": sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", method }),
  });
}

// Returns the structured result of a tool call; throws with Modelfy's error if it failed.
async function tool(name, args = {}) {
  const r = await rpc("tools/call", { name, arguments: args });
  const text = (r.content ?? []).filter((c) => c.type === "text").map((c) => c.text).join("\n");
  if (r.isError) {
    let err = text;
    try { err = JSON.stringify(JSON.parse(text).error ?? text); } catch {}
    throw new Error(`${name} failed: ${err}`);
  }
  return r.structuredContent ?? JSON.parse(text);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- the job ----
await rpc("initialize", {
  protocolVersion: "2025-06-18",
  capabilities: {},
  clientInfo: { name: "make-photos", version: "1.0.0" },
});
await notify("notifications/initialized");

// 1. Upload the product photo from this machine.
const bytes = await readFile(PRODUCT_IMAGE);
const session = await tool("create_upload_session", {
  files: [{ content_type: "image/png", bytes: bytes.length }],
});
const file = session.uploads[0];
const put = await fetch(file.put_url, { method: "PUT", headers: file.headers, body: bytes });
if (!put.ok) throw new Error(`Upload of tee.png failed: HTTP ${put.status}`);

// Wait until Modelfy has accepted the file.
let uploadId;
for (let i = 0; i < 30 && !uploadId; i++) {
  const up = await tool("get_uploaded_photos", { session_id: session.session_id });
  const ready = up.ready ?? up.photos?.filter?.((p) => p.upload_id) ?? [];
  uploadId = ready[0]?.upload_id ?? ready[0];
  if (!uploadId) {
    if (up.rejected?.length) throw new Error(`Modelfy rejected tee.png: ${JSON.stringify(up.rejected)}`);
    await sleep(2000);
  }
}
if (!uploadId) throw new Error("Timed out waiting for Modelfy to accept tee.png");

// 2. Plan: a plain studio background, product only (no model), 4 photos.
const plan = await tool("plan_photos", {
  products: [{ upload_ids: [uploadId], name: PRODUCT_NAME }],
  mode: "studio",
  background_color: "light grey",
  model_ids: [],
  aspect_ratio: ASPECT_RATIO,
  photos_per_product: PHOTOS,
  locale: "en",
});
console.error(`Plan: ${plan.credits} credits for ${PHOTOS} photos (balance ${plan.balance}).`);

// 3. Launch the planned session (nothing else is charged; retries with the same quote are safe).
const launch = await tool("generate_photos", { quote_id: plan.quote_id, user_confirmed: true });
const sid = launch.session_id;
console.error(`Session ${sid} started.`);

// 4. Wait until finished.
let done;
for (;;) {
  done = await tool("get_photo_session", { session_id: sid, wait_seconds: 45 });
  if (done.status !== "running") break;
  console.error("Still running...");
}
console.error(`Session status: ${done.status}`);

// 5. Print the links.
const photos = done.photos ?? [];
for (const p of photos) {
  console.log(p.url ?? p.link ?? p.web_url ?? JSON.stringify(p));
}
if (done.web_url) console.log(`All photos: ${done.web_url}`);
if (done.status === "failed" || (photos.length === 0)) process.exit(1);

