mkdir -p /tmp/explore && cat > /tmp/explore/mcp.mjs <<'EOF'
import { readFileSync } from "node:fs";
const env = Object.fromEntries(readFileSync("/work/.env","utf8").split("\n").filter(Boolean).map(l=>l.split(/=(.*)/s).slice(0,2)));
const URL_ = "https://mcp-dev.modelfy.ai/mcp";
let sid, id = 0;
async function rpc(method, params, notify=false) {
  const body = notify ? { jsonrpc: "2.0", method, params } : { jsonrpc: "2.0", id: ++id, method, params };
  const r = await fetch(URL_, { method: "POST", headers: { "content-type": "application/json", accept: "application/json, text/event-stream", authorization: `Bearer ${env.MODELFY_API_KEY}`, ...(sid ? {"mcp-session-id": sid} : {}) }, body: JSON.stringify(body) });
  if (r.headers.get("mcp-session-id")) sid = r.headers.get("mcp-session-id");
  if (notify) return null;
  const text = await r.text();
  const m = text.match(/^data: (.*)$/m);
  const j = JSON.parse(m ? m[1] : text);
  if (j.error) throw new Error(JSON.stringify(j.error));
  return j.result;
}
await rpc("initialize", { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "explore", version: "1" } });
await rpc("notifications/initialized", {}, true);
export { rpc };
if (process.argv[2] === "list") {
  const r = await rpc("tools/list", {});
  for (const t of r.tools) console.log(JSON.stringify({ name: t.name, schema: t.inputSchema }, null, 1));
} else if (process.argv[2] === "call") {
  const r = await rpc("tools/call", { name: process.argv[3], arguments: JSON.parse(process.argv[4] || "{}") });
  console.log(JSON.stringify(r, null, 1));
}
EOF
cd /tmp/explore && node mcp.mjs list 2>&1 | head -c 20000

