#!/usr/bin/env node
// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy and
// prints the links to the finished photos.
//
// Usage:  node --env-file=.env make-photos.mjs
// Needs:  MODELFY_API_KEY in the environment (Node 20.6+ can load it from .env
//         with --env-file, as above).

import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const MCP_URL = "https://mcp-dev.modelfy.ai/mcp";
const PHOTO_FILE = join(dirname(fileURLToPath(import.meta.url)), "tee.png");
const PRODUCT_NAME = "Linen T-shirt";
const PHOTO_COUNT = 4;
const ASPECT_RATIO = "4:5";
const STUDIO_COLOR = "white";

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env and run: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP -------------------------------

let sessionId;
let nextId = 1;

async function rpc(method, params, { notification = false } = {}) {
  const body = notification
    ? { jsonrpc: "2.0", method, params }
    : { jsonrpc: "2.0", id: nextId++, method, params };
  const res = await fetch(MCP_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      accept: "application/json, text/event-stream",
      authorization: `Bearer ${apiKey}`,
      ...(sessionId ? { "mcp-session-id": sessionId } : {}),
    },
    body: JSON.stringify(body),
  });
  sessionId ??= res.headers.get("mcp-session-id") ?? undefined;
  if (notification) return null;

  const text = await res.text();
  if (!res.ok) throw new Error(`Modelfy HTTP ${res.status}: ${text.slice(0, 300)}`);
  // The server may answer with plain JSON or with a single SSE event.
  const data = text.match(/^data: (.*)$/m)?.[1] ?? text;
  const reply = JSON.parse(data);
  if (reply.error) throw new Error(`MCP error: ${JSON.stringify(reply.error)}`);
  return reply.result;
}

// Calls a Modelfy tool and returns its structured result. Tool failures
// (isError) come back as a JSON error object with a stable `code`.
async function callTool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  const payload = result.structuredContent ?? JSON.parse(result.content.at(-1).text);
  if (result.isError) {
    const err = payload?.error ?? {};
    throw new Error(`${name} failed [${err.code ?? "ERROR"}]: ${err.message ?? result.content[0]?.text}${err.next_step ? ` Next: ${err.next_step}` : ""}`);
  }
  return payload;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- Workflow ----------------------------------------------------------------

async function uploadPhoto() {
  const bytes = await readFile(PHOTO_FILE);
  const session = await callTool("create_upload_session", {
    files: [{ content_type: "image/png", bytes: bytes.length }],
  });
  const target = session.uploads[0];

  const put = await fetch(target.put_url, {
    method: "PUT",
    headers: target.headers,
    body: bytes,
  });
  if (!put.ok) throw new Error(`Upload of ${PHOTO_FILE} failed: HTTP ${put.status}`);

  for (let i = 0; i < 30; i++) {
    const status = await callTool("get_uploaded_photos", { session_id: session.session_id });
    if (status.rejected?.length) {
      throw new Error(`Modelfy rejected the photo: ${status.rejected[0].reason ?? JSON.stringify(status.rejected[0])}`);
    }
    if (status.ready_upload_ids?.length) return status.ready_upload_ids[0];
    await sleep(1000);
  }
  throw new Error("Timed out waiting for Modelfy to process the photo");
}

async function main() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  await rpc("notifications/initialized", {}, { notification: true });

  const account = await callTool("get_account");
  console.error(`Account: ${account.plan}, ${account.credits} credits${account.sandbox ? " (sandbox: photos are samples, nothing is spent)" : ""}`);

  console.error("Uploading tee.png...");
  const uploadId = await uploadPhoto();

  const quote = await callTool("plan_photos", {
    products: [{ upload_ids: [uploadId], name: PRODUCT_NAME }],
    mode: "studio",
    background_color: STUDIO_COLOR,
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTO_COUNT,
    locale: "en",
  });
  console.error(`Plan: ${quote.photos} photos for ${quote.credits} credits (balance ${quote.balance}).`);
  if (!quote.enough_credits) {
    throw new Error(`Not enough credits: need ${quote.credits}, have ${quote.balance}.`);
  }

  const launch = await callTool("generate_photos", { quote_id: quote.quote_id });
  const sessionIdModelfy = launch.session_id;
  console.error(`Session ${sessionIdModelfy} started. Waiting for photos...`);

  let session = launch;
  for (let i = 0; i < 40 && session.status === "running"; i++) {
    session = await callTool("get_photo_session", { session_id: sessionIdModelfy, wait_seconds: 45 });
    console.error(`  ${session.done}/${session.total} done, ${session.failed} failed`);
  }
  if (session.status === "running") {
    throw new Error(`Session ${sessionIdModelfy} is still running. Check it later with get_photo_session.`);
  }

  console.error(`Status: ${session.status}`);
  console.log(`Finished photos (${session.done} of ${session.total}):`);
  for (const photo of session.photos) console.log(photo.url);
  console.log(`All photos: ${session.web_url}`);

  if (session.done === 0) process.exitCode = 1;
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

